<x-capstone::card class="h-full" x-data="capstoneCalendar">
    <div class="px-6 pb-3 flex flex-row items-center justify-between"><h3 class="text-base font-semibold">Schedule</h3><div class="flex items-center gap-1"><x-capstone::button variant="ghost" size="icon" class="h-7 w-7" @click="move(-1)" aria-label="Previous month"><x-capstone::icon name="ChevronLeft" /></x-capstone::button><x-capstone::button variant="ghost" size="icon" class="h-7 w-7" @click="move(1)" aria-label="Next month"><x-capstone::icon name="ChevronRight" /></x-capstone::button></div></div>
    <div class="px-6 pt-0"><h3 class="text-center mb-3 text-lg font-semibold" x-text="monthLabel"></h3><div class="grid grid-cols-7 mb-1">@foreach(['Mo','Tu','We','Th','Fr','Sa','Su'] as $day)<div class="text-center text-xs font-medium text-gray-400 py-1">{{ $day }}</div>@endforeach</div><div class="grid grid-cols-7 gap-px bg-gray-100 border border-gray-100 rounded-lg overflow-hidden"><template x-for="day in days" :key="day.key"><div class="min-h-[40px] p-1 flex flex-col items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors" :class="day.today ? 'bg-primary-50' : day.current ? 'bg-white' : 'bg-gray-50 text-gray-300'" :title="eventsFor(day,schedules).map(e=>e.title || e.student_name || e.type).join('\n')"><span class="text-sm font-medium" x-text="day.number"></span><div class="flex gap-0.5 mt-0.5"><template x-for="(event,index) in eventsFor(day,schedules).slice(0,3)" :key="index"><span class="w-1.5 h-1.5 rounded-full" :class="eventColor(event.type)"></span></template></div></div></template></div></div>
